import "@fontsource/space-mono/400.css";
import "@fontsource/unbounded/800.css";
import "./style.css";
import * as THREE from "three";

const FOG = new THREE.Color("#a3aba6");
const canvas = document.getElementById("scene");
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;

const scene = new THREE.Scene();
scene.background = FOG;
scene.fog = new THREE.Fog(FOG, 14, 70);
const camera = new THREE.PerspectiveCamera(38, 1, 0.05, 200);

// --- lights
scene.add(new THREE.HemisphereLight("#eef3ef", "#56634f", 1.6));
const sun = new THREE.DirectionalLight("#fffaf0", 2.2);
sun.position.set(-8, 14, 6);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
Object.assign(sun.shadow.camera, { left: -8, right: 8, top: 8, bottom: -8, near: 1, far: 40 });
sun.shadow.bias = -0.0004;
scene.add(sun);

// --- terrain: value-noise hills, a flattened green around the hole, one bunker
const hash = (x, y) => { const s = Math.sin(x * 127.1 + y * 311.7) * 43758.5453; return s - Math.floor(s); };
const smooth = (t) => t * t * (3 - 2 * t);
function noise(x, y) {
  const xi = Math.floor(x), yi = Math.floor(y), xf = smooth(x - xi), yf = smooth(y - yi);
  const a = hash(xi, yi), b = hash(xi + 1, yi), c = hash(xi, yi + 1), d = hash(xi + 1, yi + 1);
  return a + (b - a) * xf + (c - a) * yf + (a - b - c + d) * xf * yf;
}
const fbm = (x, y) => noise(x, y) * 0.5 + noise(x * 2.1, y * 2.1) * 0.25 + noise(x * 4.3, y * 4.3) * 0.125;
const GREEN_R = 7, BUNKER = new THREE.Vector2(-6.5, 4.5);
function height(x, z) {
  const r = Math.hypot(x, z);
  const hills = (fbm(x * 0.06 + 3, z * 0.06 + 7) - 0.45) * 9 + Math.max(0, r - 18) * 0.12;
  const green = 0.08 * Math.sin(x * 0.35) + 0.06 * Math.cos(z * 0.4); // gentle putting break
  const t = smooth(THREE.MathUtils.clamp((r - GREEN_R) / 10, 0, 1));
  let h = green + (hills - green) * t + fbm(x * 0.8, z * 0.8) * 0.12 * t;
  const bd = Math.hypot((x - BUNKER.x) / 2.6, (z - BUNKER.y) / 1.6);
  if (bd < 1) h -= 0.45 * smooth(1 - bd);
  return h;
}
function surface(x, z) { // 0 green, 1 rough, 2 sand
  if (Math.hypot((x - BUNKER.x) / 2.6, (z - BUNKER.y) / 1.6) < 0.85) return 2;
  return Math.hypot(x, z) < GREEN_R + fbm(x * 0.5, z * 0.5) * 1.5 ? 0 : 1;
}

const grain = (() => { // tiling grass grain texture, generated so there are no image files
  const c = document.createElement("canvas"); c.width = c.height = 256;
  const g = c.getContext("2d"), img = g.createImageData(256, 256);
  for (let i = 0; i < img.data.length; i += 4) { const v = 200 + Math.random() * 55; img.data.set([v, v, v, 255], i); }
  g.putImageData(img, 0, 0);
  const t = new THREE.CanvasTexture(c); t.wrapS = t.wrapT = THREE.RepeatWrapping; t.repeat.set(90, 90); t.colorSpace = THREE.SRGBColorSpace;
  return t;
})();

const geo = new THREE.PlaneGeometry(160, 160, 320, 320).rotateX(-Math.PI / 2);
const pos = geo.attributes.position, colors = [];
const C = [new THREE.Color("#7f9a73"), new THREE.Color("#5f7656"), new THREE.Color("#d6cdb4")];
const tmp = new THREE.Color();
for (let i = 0; i < pos.count; i++) {
  const x = pos.getX(i), z = pos.getZ(i);
  pos.setY(i, height(x, z));
  const s = surface(x, z);
  tmp.copy(C[s]);
  if (s === 0) tmp.offsetHSL(0, 0, (Math.sin(x * 1.2 + z * 0.4) > 0 ? 0.025 : -0.015)); // mowing stripes
  else if (s === 1) tmp.offsetHSL(0, 0, (fbm(x * 0.3, z * 0.3) - 0.45) * 0.12);
  colors.push(tmp.r, tmp.g, tmp.b);
}
geo.setAttribute("color", new THREE.Float32BufferAttribute(colors, 3));
geo.computeVertexNormals();
const ground = new THREE.Mesh(geo, new THREE.MeshStandardMaterial({ vertexColors: true, map: grain, roughness: 0.95 }));
ground.receiveShadow = true;
scene.add(ground);

// --- the hole, flagstick, flag, ball
const H0 = height(0, 0);
const cup = new THREE.Mesh(new THREE.CircleGeometry(0.11, 40).rotateX(-Math.PI / 2), new THREE.MeshBasicMaterial({ color: "#0d100c" }));
cup.position.set(0, H0 + 0.006, 0);
const rim = new THREE.Mesh(new THREE.RingGeometry(0.11, 0.125, 40).rotateX(-Math.PI / 2), new THREE.MeshStandardMaterial({ color: "#f4f4f0" }));
rim.position.copy(cup.position);
scene.add(cup, rim);

const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.018, 0.018, 2.4, 12), new THREE.MeshStandardMaterial({ color: "#f5f3ea", roughness: 0.4 }));
pole.position.set(0, H0 + 1.2, 0);
pole.castShadow = true;
scene.add(pole);

const FW = 0.9, FH = 0.58;
const flagGeo = new THREE.PlaneGeometry(FW, FH, 24, 12).translate(FW / 2, 0, 0);
const flagRest = flagGeo.attributes.position.array.slice();
const flag = new THREE.Mesh(flagGeo, new THREE.MeshStandardMaterial({ color: "#e5483a", side: THREE.DoubleSide, roughness: 0.7 }));
flag.position.set(0.015, H0 + 2.4 - FH / 2 - 0.02, 0);
flag.castShadow = true;
scene.add(flag);

const BALL = new THREE.Vector3(1.6, 0, 1.1);
BALL.y = height(BALL.x, BALL.z) + 0.045;
const ball = new THREE.Mesh(new THREE.SphereGeometry(0.045, 24, 16), new THREE.MeshStandardMaterial({ color: "#ffffff", roughness: 0.35 }));
ball.position.copy(BALL);
ball.castShadow = true;
scene.add(ball);

// --- coach overlay: putting line + numbered read points (like a constellation)
const lineMat = new THREE.LineBasicMaterial({ color: "#ffffff", transparent: true, opacity: 0.8, fog: false });
const lift = (x, z, y = 0.03) => new THREE.Vector3(x, height(x, z) + y, z);
const putt = new THREE.CatmullRomCurve3([lift(BALL.x, BALL.z), lift(1.1, 1.0), lift(0.5, 0.55), lift(0, 0)]);
scene.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(putt.getPoints(60)), lineMat));

const reads = [[-2.2, 2.6, 0.9, "53"], [0.6, 3.4, 1.6, "68"], [-3.4, -0.6, 1.2, "63"], [1.2, -1.8, 0.5, "26"], [3.4, 0.4, 0.7, "29"]]
  .map(([x, z, y, n]) => ({ p: lift(x, z, y), n }));
const order = [2, 0, 1, 4, 3, 2, 1, 3];
scene.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(order.map((i) => reads[i].p)), lineMat));
const labelsEl = document.getElementById("labels");
const tags = reads.map(({ p, n }) => { const el = document.createElement("span"); el.className = "tag"; el.textContent = n; labelsEl.append(el); return { el, p }; });

// --- floating wireframe strokes and drifting specks in the mist
const segs = [];
for (let i = 0; i < 70; i++) {
  const a = new THREE.Vector3((Math.random() - 0.5) * 30, 1 + Math.random() * 8, (Math.random() - 0.5) * 30 - 4);
  const axis = [new THREE.Vector3(1, 0, 0), new THREE.Vector3(0, 1, 0), new THREE.Vector3(0, 0, 1)][i % 3];
  segs.push(a, a.clone().addScaledVector(axis, 1 + Math.random() * 3));
}
const strokes = new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(segs), new THREE.LineBasicMaterial({ color: "#ffffff", transparent: true, opacity: 0.35 }));
scene.add(strokes);
const specks = new THREE.Points(
  new THREE.BufferGeometry().setFromPoints(Array.from({ length: 400 }, () => new THREE.Vector3((Math.random() - 0.5) * 40, Math.random() * 10, (Math.random() - 0.5) * 40))),
  new THREE.PointsMaterial({ color: "#ffffff", size: 0.04, transparent: true, opacity: 0.7 }));
scene.add(specks);

// --- camera path driven by scroll (one key per section)
const keys = [
  { p: [6.5, 4.2, 7.5], t: [0, 0.9, 0] },
  { p: [-5.5, 2.4, 5.5], t: [0, 1.2, 0] },
  { p: [3.2, 0.5, 2.6], t: [0, 0.25, 0] },
  { p: [0.4, 9.5, 2.2], t: [0, 0, 0] },
].map(({ p, t }) => ({ p: new THREE.Vector3(...p), t: new THREE.Vector3(...t) }));
const camPos = new THREE.Vector3(), camTgt = new THREE.Vector3();
const mouse = new THREE.Vector2(), mouseS = new THREE.Vector2();
addEventListener("pointermove", (e) => mouse.set(e.clientX / innerWidth - 0.5, e.clientY / innerHeight - 0.5));

const hudBottom = document.querySelector(".hud-bottom p");
function scrollProgress() {
  const max = document.documentElement.scrollHeight - innerHeight;
  return max > 0 ? scrollY / max : 0;
}

function resize() {
  const w = innerWidth, h = innerHeight;
  renderer.setSize(w, h, false);
  camera.aspect = w / h;
  camera.fov = w / h < 1 ? 52 : 38; // portrait screens: widen so the flag still fits
  camera.updateProjectionMatrix();
}
addEventListener("resize", resize);
resize();

