  smoothP += (scrollProgress() - smoothP) * 0.08;
  const f = smoothP * (keys.length - 1), i = Math.min(Math.floor(f), keys.length - 2), k = smooth(f - i);
  camPos.lerpVectors(keys[i].p, keys[i + 1].p, k);
