  if (camera.aspect < 1) camPos.sub(camTgt).multiplyScalar(1.25).add(camTgt);
  mouseS.lerp(mouse, 0.05);
  camera.position.copy(camPos).add(v.set(mouseS.x * 0.6, -mouseS.y * 0.3, 0));
  camera.lookAt(camTgt);

  // flag wave: displacement grows away from the pole
  const a = flagGeo.attributes.position;
  for (let j = 0; j < a.count; j++) {
    const x = flagRest[j * 3], y = flagRest[j * 3 + 1], w = x / FW;
    a.setZ(j, reduce ? w * 0.08 : Math.sin(x * 6 - t * 4 + y * 2) * 0.09 * w + Math.sin(x * 3 - t * 2.3) * 0.05 * w);
  }
  a.needsUpdate = true;
  flagGeo.computeVertexNormals();

  if (!reduce) { strokes.position.y = Math.sin(t * 0.3) * 0.3; specks.rotation.y = t * 0.02; }

  for (const { el, p } of tags) {
    v.copy(p).project(camera);
    const vis = v.z < 1 && Math.abs(v.x) < 1.1 && Math.abs(v.y) < 1.1;
    el.style.opacity = vis ? 1 : 0;
    el.style.transform = `translate(${((v.x + 1) / 2) * innerWidth + 6}px, ${((1 - v.y) / 2) * innerHeight - 14}px)`;
  }
  hudBottom.style.opacity = Math.max(0, 1 - scrollY / 200);
  renderer.render(scene, camera);
});

// --- sound: soft procedural wind (no audio files)
const btn = document.getElementById("sound");
let ctx, gain;
btn.addEventListener("click", () => {
  if (!ctx) {
    ctx = new AudioContext();
    const buf = ctx.createBuffer(1, ctx.sampleRate * 4, ctx.sampleRate), d = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < d.length; i++) { last = (last + 0.02 * (Math.random() * 2 - 1)) / 1.02; d[i] = last * 3.5; }
    const src = Object.assign(ctx.createBufferSource(), { buffer: buf, loop: true });
    const lp = Object.assign(ctx.createBiquadFilter(), { type: "lowpass" }); lp.frequency.value = 500;
    gain = ctx.createGain(); gain.gain.value = 0;
    src.connect(lp).connect(gain).connect(ctx.destination); src.start();
  }
  const on = btn.getAttribute("aria-pressed") !== "true";
  btn.setAttribute("aria-pressed", on);
  btn.querySelector("b").textContent = on ? "On" : "Off";
  ctx.resume();
  gain.gain.setTargetAtTime(on ? 0.5 : 0, ctx.currentTime, 0.3);
});

