scene.add(new THREE.HemisphereLight("#eef3ef", "#56634f", 1.6));
const sun = new THREE.DirectionalLight("#fffaf0", 2.2);
sun.position.set(-8, 14, 6);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
