const segs = [];
for (let i = 0; i < 70; i++) {
  const a = new THREE.Vector3((Math.random() - 0.5) * 30, 1 + Math.random() * 8, (Math.random() - 0.5) * 30 - 4);
  const axis = [new THREE.Vector3(1, 0, 0), new THREE.Vector3(0, 1, 0), new THREE.Vector3(0, 0, 1)][i % 3];
  segs.push(a, a.clone().addScaledVector(axis, 1 + Math.random() * 3));
}
const strokes = new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(segs), new THREE.LineBasicMaterial({ color: "#ffffff", transparent: true, opacity: 0.35 }));
scene.add(strokes);
const specks = new THREE.Points(
  new THREE.BufferGeometry().setFromPoints(Array.from({ length: 400 }, () => new THREE.Vector3((Math.random() - 0.5) * 40, Math.random() * 10, (Math.random() - 0.5) * 40))),
