// --- mini putting game: point at the green to aim, click / tap to putt
const ray = new THREE.Raycaster(), ndc = new THREE.Vector2(), aim = new THREE.Vector3();
function groundPoint(cx, cy) { // ray vs terrain: start on a flat plane, refine with the real height
  ndc.set((cx / innerWidth) * 2 - 1, -(cy / innerHeight) * 2 + 1);
  ray.setFromCamera(ndc, camera);
  const { origin: o, direction: d } = ray.ray;
  if (d.y >= -0.01) return null;
  let y = H0;
  for (let n = 0; n < 4; n++) { aim.copy(o).addScaledVector(d, (y - o.y) / d.y); y = height(aim.x, aim.z); }
  aim.y = y;
  return aim;
}
const FRICTION = 1.5;
const game = { vel: new THREE.Vector2(), rolling: false, holed: false, putts: 0, made: 0 };
const playable = () => goal < 0.3 && !game.rolling && !game.holed;
const toastEl = document.getElementById("toast");
let toastTimer;
function toast(msg) { toastEl.textContent = msg; toastEl.classList.add("on"); clearTimeout(toastTimer); toastTimer = setTimeout(() => toastEl.classList.remove("on"), 2200); }

canvas.addEventListener("pointermove", (e) => {
  const pt = playable() && groundPoint(e.clientX, e.clientY);
  aimLine.visible = aimRing.visible = !!pt && pt.distanceTo(ball.position) < 9;
  if (!aimLine.visible) return;
  aimLine.geometry.setFromPoints([ball.position.clone().setY(ball.position.y + 0.01), pt.clone().setY(pt.y + 0.02)]);
  aimLine.computeLineDistances();
  aimRing.position.set(pt.x, pt.y + 0.015, pt.z);
});
let downAt = null;
canvas.addEventListener("pointerdown", (e) => { downAt = [e.clientX, e.clientY]; });
canvas.addEventListener("pointerup", (e) => {
  if (!downAt || Math.hypot(e.clientX - downAt[0], e.clientY - downAt[1]) > 8 || !playable()) return;
  const pt = groundPoint(e.clientX, e.clientY);
  if (!pt) return;
  const dx = pt.x - ball.position.x, dz = pt.z - ball.position.z;
  if (Math.hypot(dx, dz) > 9) return;
  game.vel.set(dx, dz).multiplyScalar(FRICTION); // linear drag: the ball stops near the point you picked
  game.rolling = true; game.putts++;
  aimLine.visible = aimRing.visible = readLine.visible = false;
  blip(240, 0.06);
});
function respawn() {
  const ang = Math.random() * Math.PI * 2, r = 1.4 + Math.random() * 2.6;
  ball.position.set(Math.cos(ang) * r, 0, Math.sin(ang) * r);
  ball.position.y = height(ball.position.x, ball.position.z) + 0.045;
  Object.assign(game, { holed: false, putts: 0 });
  readLine.visible = true; drawRead();
}
function stepBall(dt) {
  const b = ball.position;
  if (game.holed) { b.y = Math.max(H0 - 0.08, b.y - dt * 0.6); return; }
  if (!game.rolling) return;
  game.vel.addScaledVector(slope(b.x, b.z), -9.8 * 0.08 * dt).multiplyScalar(Math.exp(-FRICTION * dt));
  b.x += game.vel.x * dt; b.z += game.vel.y * dt;
  b.y = height(b.x, b.z) + 0.045;
  ball.rotation.x += (game.vel.y * dt) / 0.045; ball.rotation.z -= (game.vel.x * dt) / 0.045;
  const toCup = Math.hypot(b.x, b.z), speed = game.vel.length();
  if (toCup < 0.1 && speed < 1.4) { // dropped in
    game.rolling = false; game.holed = true; game.made++;
    b.x = b.z = 0;
    toast(game.putts === 1 ? "In the hole. One putt!" : `Holed in ${game.putts}. Nice touch.`);
    blip(880, 0.25); setTimeout(() => blip(1320, 0.2), 120);
    setTimeout(respawn, 2400);
  } else if (speed < 0.04 || toCup > 11) {
    game.rolling = false;
    if (toCup > 11) respawn(); else { readLine.visible = true; drawRead(); }
  }
}

