toolUseResult.originalFile:
:root {
  --bg: #ece9e0;
  --ink: #1e211b;
  --muted: #4a4e44;
  --accent: #5c7a2a;
  --accent-strong: #465e1f;
  --gold: #e8c547;
  --line: #c9c5b8;
  --pad: clamp(24px, 6.5vw, 50px);
  --mono: "Space Mono", ui-monospace, monospace;
  --display: "Anton", Impact, system-ui, sans-serif;
}
* { box-sizing: border-box; margin: 0; }
html, body { background: var(--bg); color: var(--ink); overflow-x: hidden; }
body { font-family: var(--mono); -webkit-font-smoothing: antialiased; }
#scene { position: fixed; inset: 0; width: 100%; height: 100%; display: block; }
#labels { position: fixed; inset: 0; pointer-events: none; overflow: hidden; }
.tag { position: absolute; left: 0; top: 0; font: 400 11px/1 var(--mono); color: var(--ink); text-shadow: 0 0 6px rgba(242,240,232,.8); white-space: nowrap; }
.tag::before { content: "+"; position: absolute; left: -4px; top: 6px; font-size: 13px; }

.mono { font: 400 12px/1.32 var(--mono); letter-spacing: .01em; text-shadow: 0 0 8px rgba(242,240,232,.6); }
.hud { position: fixed; z-index: 2; animation: fade 1.2s .2s both; }
.hud-left { top: var(--pad); left: var(--pad); }
.hud-left .mono { margin-top: 12px; }
.hud-left .mono + .mono { margin-top: 14px; }
.logo { display: inline-flex; align-items: flex-start; font: 400 clamp(32px, 6.4vw, 62px)/0.8 var(--display); letter-spacing: .01em; color: var(--ink); text-decoration: none; text-transform: uppercase; }
.logo .flag { width: .3em; height: .8em; margin: 0 .1em 0 .12em; border-left: .07em solid currentColor; position: relative; }
.logo .flag::after { content: ""; position: absolute; left: 0; top: 0; border-left: .26em solid var(--gold); border-top: .14em solid transparent; border-bottom: .14em solid transparent; }
.hud-right { top: var(--pad); right: var(--pad); text-align: right; }
.hud-right .manifesto { margin-top: 10px; width: 11.2em; margin-left: auto; }
.hud-bottom { left: var(--pad); bottom: var(--pad); }
.sound { margin-top: 26px; display: flex; align-items: center; gap: 8px; background: none; border: 0; padding: 0; color: inherit; cursor: pointer; }
.sound b { font-weight: 400; }
.sound .w { display: none; }
.sound[aria-pressed="true"] .w { display: inline; }
.sound[aria-pressed="true"] .x { display: none; }

html, body { height: 100%; overflow: hidden; overscroll-behavior: none; }
main { position: fixed; inset: 0; z-index: 1; pointer-events: none; }
section { position: absolute; inset: 0; display: flex; align-items: center; padding: 0 var(--pad); opacity: 0; transform: translateY(24px); transition: opacity .6s, transform .6s; }
section.on { opacity: 1; transform: none; pointer-events: auto; }
.chapter.right { justify-content: flex-end; }
.panel { max-width: 340px; padding: 22px 24px; background: rgba(242, 240, 232, .78); backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px); border: 1px solid var(--line); color: var(--ink); }
.panel .kicker { color: var(--accent); }
.panel h2 { font: 400 30px/1.05 var(--display); letter-spacing: .01em; margin: 14px 0 12px; text-transform: uppercase; }
.panel p:not(.kicker) { line-height: 1.5; }
.cta { display: inline-block; margin-top: 18px; padding: 10px 14px; border: 1px solid var(--accent); background: var(--accent); color: #fff; text-decoration: none; font: inherit; transition: background .2s, color .2s; }
.cta:hover, .cta:focus-visible { background: var(--accent-strong); border-color: var(--accent-strong); }

@keyframes fade { from { opacity: 0; } to { opacity: 1; } }

@media (max-width: 500px) {
  .mono { font-size: 11px; }
  .hud-right .manifesto { width: 11.2em; }
  .panel { max-width: 100%; }
  .panel h2 { font-size: 24px; }
  section { align-items: flex-end; padding-bottom: 150px; }
}
@media (prefers-reduced-motion: reduce) { .hud { animation: none; } }

/* light falls from the upper right, like the original's scene */
body::after { content: ""; position: fixed; inset: 0; z-index: 0; pointer-events: none;
  background: linear-gradient(to top right, rgba(30, 33, 27, .22), rgba(30, 33, 27, 0) 50%, rgba(255, 250, 235, .12)); }

