// --- coach overlay: putting line + numbered read points (like a constellation)
const lineMat = new THREE.LineBasicMaterial({ color: "#1e211b", transparent: true, opacity: 0.6, fog: false });
const lift = (x, z, y = 0.03) => new THREE.Vector3(x, height(x, z) + y, z);
const slope = (x, z) => new THREE.Vector2((height(x + 0.05, z) - height(x - 0.05, z)) / 0.1, (height(x, z + 0.05) - height(x, z - 0.05)) / 0.1);
const readLine = new THREE.Line(new THREE.BufferGeometry(), lineMat);
scene.add(readLine);
const read = { dist: 0, side: "", cups: 0 };
function drawRead() { // coach's suggested line: bends against the slope across the putt
  const bx = ball.position.x, bz = ball.position.z, dist = Math.hypot(bx, bz);
  const perp = new THREE.Vector2(-bz, bx).normalize();
  const g = slope(bx / 2, bz / 2).dot(perp);
  const off = THREE.MathUtils.clamp(g * dist * 1.5, -0.8, 0.8);
  const curve = new THREE.CatmullRomCurve3([lift(bx, bz), lift(bx / 2 + perp.x * off, bz / 2 + perp.y * off), lift(0, 0)]);
  readLine.geometry.setFromPoints(curve.getPoints(60));
  Object.assign(read, { dist, side: off > 0 ? "R" : "L", cups: Math.max(0, Math.round(Math.abs(off) / 0.108)) });
}
drawRead();

const aimMat = new THREE.LineDashedMaterial({ color: "#5c7a2a", dashSize: 0.08, gapSize: 0.06, fog: false });
const aimLine = new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]), aimMat);
