aimLine.visible = aimRing.visible = false;
scene.add(aimLine, aimRing);

const reads = [[-0.9, 0.7, 1.9, "53"], [0.9, 0.6, 1.6, "68"], [-1.4, 0.2, 1.3, "63"], [-0.3, 1.1, 0.5, "26"], [1.3, 0.9, 0.6, "29"]]
  .map(([x, z, y, n]) => ({ p: lift(x, z, y), n }));
const order = [2, 0, 3, 1, 4];
scene.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(order.map((i) => reads[i].p)), lineMat));
const labelsEl = document.getElementById("labels");
const tips = ["Grain: into the sun", "Slope 1.4% · uphill", "Firm fringe · 9.8 stimp", "Break 2 cups left", "Moisture 18%"];
const tags = reads.map(({ p, n }, i) => {
  const el = document.createElement("span"); el.className = "tag"; el.textContent = n; el.dataset.tip = tips[i]; el.tabIndex = 0;
  labelsEl.append(el); return { el, p };
});

// --- floating wireframe strokes and drifting specks in the mist
const segs = [];
for (let i = 0; i < 70; i++) {
  const a = new THREE.Vector3((Math.random() - 0.5) * 30, 1 + Math.random() * 8, (Math.random() - 0.5) * 30 - 4);
  const axis = [new THREE.Vector3(1, 0, 0), new THREE.Vector3(0, 1, 0), new THREE.Vector3(0, 0, 1)][i % 3];
  segs.push(a, a.clone().addScaledVector(axis, 1 + Math.random() * 3));
}
const strokes = new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(segs), new THREE.LineBasicMaterial({ color: "#5c7a2a", transparent: true, opacity: 0.3 }));
scene.add(strokes);
const specks = new THREE.Points(
  new THREE.BufferGeometry().setFromPoints(Array.from({ length: 400 }, () => new THREE.Vector3((Math.random() - 0.5) * 40, Math.random() * 10, (Math.random() - 0.5) * 40))),
  new THREE.PointsMaterial({ color: "#ffffff", size: 0.04, transparent: true, opacity: 0.7 }));
scene.add(specks);

// distant trees and tufts of rough around the green
const rnd = (a, b) => a + Math.random() * (b - a);
const dummy = new THREE.Object3D();
const trees = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(1.6, 1).scale(1, 1.25, 1).translate(0, 2.2, 0), new THREE.MeshStandardMaterial({ color: "#3f5222", roughness: 1, flatShading: true }), 70);
for (let n = 0; n < trees.count; n++) {
  const ang = rnd(0, Math.PI * 2), r = rnd(15, 38), x = Math.cos(ang) * r, z = Math.sin(ang) * r; // ring stays clear of every camera stop
  const sc = rnd(0.8, 1.7);
  dummy.position.set(x, height(x, z) - 0.1, z); dummy.scale.set(sc, sc * rnd(0.9, 1.4), sc); dummy.rotation.set(0, rnd(0, 6), 0);
  dummy.updateMatrix(); trees.setMatrixAt(n, dummy.matrix);
}
trees.castShadow = true;
scene.add(trees);
const tufts = new THREE.InstancedMesh(new THREE.ConeGeometry(0.025, 0.16, 3).translate(0, 0.08, 0), new THREE.MeshStandardMaterial({ color: "#ffffff", roughness: 1 }), 2600);
for (let n = 0; n < tufts.count; n++) {
  const ang = rnd(0, Math.PI * 2), r = rnd(GREEN_R + 1.2, GREEN_R + 7), x = Math.cos(ang) * r, z = Math.sin(ang) * r;
  dummy.position.set(x, height(x, z), z); dummy.rotation.set(rnd(-0.3, 0.3), 0, rnd(-0.3, 0.3)); dummy.scale.setScalar(rnd(0.6, 1.4));
  dummy.updateMatrix(); tufts.setMatrixAt(n, dummy.matrix);
  tufts.setColorAt(n, tmp.set("#4f6826").offsetHSL(rnd(-0.02, 0.02), 0, rnd(-0.06, 0.08)));
}
scene.add(tufts);

// soft light haze in the upper-right sky
const haze = new THREE.Sprite(new THREE.SpriteMaterial({ fog: false, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, opacity: 0.55,
  map: (() => { const c = document.createElement("canvas"); c.width = c.height = 128; const g = c.getContext("2d");
    const gr = g.createRadialGradient(64, 64, 0, 64, 64, 64); gr.addColorStop(0, "rgba(255,250,235,.6)"); gr.addColorStop(1, "rgba(255,255,255,0)");
    g.fillStyle = gr; g.fillRect(0, 0, 128, 128); return new THREE.CanvasTexture(c); })() }));
haze.position.set(14, 9, -30);
haze.scale.set(60, 40, 1);
scene.add(haze);

// --- camera path driven by scroll (one key per section)
const keys = [
  { p: [4.2, 3.6, 4.8], t: [0, 0.75, 0] },
  { p: [-5.5, 2.4, 5.5], t: [0, 1.2, 0] },
  { p: [3.2, 0.5, 2.6], t: [0, 0.25, 0] },
  { p: [0.4, 9.5, 2.2], t: [0, 0, 0] },
].map(({ p, t }) => ({ p: new THREE.Vector3(...p), t: new THREE.Vector3(...t) }));
const camPos = new THREE.Vector3(), camTgt = new THREE.Vector3();
const mouse = new THREE.Vector2(), mouseS = new THREE.Vector2();
addEventListener("pointermove", (e) => mouse.set(e.clientX / innerWidth - 0.5, e.clientY / innerHeight - 0.5));

const hudBottom = document.querySelector(".hud-bottom p");
const chapters = [...document.querySelectorAll(".chapter")];
// One screen, no page scroll: wheel / touch / keys move along the camera path.
const MAX = keys.length - 1;
let goal = 0;
const nudge = (d) => { goal = THREE.MathUtils.clamp(goal + d, 0, MAX); };
addEventListener("wheel", (e) => nudge(e.deltaY / 900), { passive: true });
let touchY = null;
addEventListener("touchstart", (e) => { touchY = e.touches[0].clientY; }, { passive: true });
addEventListener("touchmove", (e) => { const y = e.touches[0].clientY; nudge((touchY - y) / innerHeight * 1.6); touchY = y; }, { passive: true });
addEventListener("keydown", (e) => {
  const step = { ArrowDown: 1, PageDown: 1, " ": 1, ArrowUp: -1, PageUp: -1 }[e.key];
  if (step) { goal = THREE.MathUtils.clamp(Math.round(goal) + step, 0, MAX); e.preventDefault(); }
  if (e.key === "Home") goal = 0;
  if (e.key === "End") goal = MAX;
});
const scrollProgress = () => goal / MAX;

// --- mini putting game: point at the green to aim, click / tap to putt
const ray = new THREE.Raycaster(), ndc = new THREE.Vector2(), aim = new THREE.Vector3();
function groundPoint(cx, cy) { // ray vs terrain: start on a flat plane, refine with the real height
  ndc.set((cx / innerWidth) * 2 - 1, -(cy / innerHeight) * 2 + 1);
  ray.setFromCamera(ndc, camera);
  const { origin: o, direction: d } = ray.ray;
  if (d.y >= -0.01) return null;
  let y = H0;
  for (let n = 0; n < 4; n++) { aim.copy(o).addScaledVector(d, (y - o.y) / d.y); y = height(aim.x, aim.z); }
  aim.y = y;
  return aim;
}
const MU = 0.6; // green friction, m/s²; stronger than the steepest slope pull (~0.2) so a ball always comes to rest
const game = { vel: new THREE.Vector2(), rolling: false, holed: false, putts: 0, made: 0 };
const playable = () => goal < 0.3 && !game.rolling && !game.holed;
const toastEl = document.getElementById("toast");
let toastTimer;
function toast(msg) { toastEl.textContent = msg; toastEl.classList.add("on"); clearTimeout(toastTimer); toastTimer = setTimeout(() => toastEl.classList.remove("on"), 2200); }

canvas.addEventListener("pointermove", (e) => {
  const pt = playable() && groundPoint(e.clientX, e.clientY);
  aimLine.visible = aimRing.visible = !!pt && pt.distanceTo(ball.position) < 9;
  if (!aimLine.visible) return;
  aimLine.geometry.setFromPoints([ball.position.clone().setY(ball.position.y + 0.01), pt.clone().setY(pt.y + 0.02)]);
  aimLine.computeLineDistances();
  aimRing.position.set(pt.x, pt.y + 0.015, pt.z);
});
let downAt = null;
canvas.addEventListener("pointerdown", (e) => { downAt = [e.clientX, e.clientY]; });
canvas.addEventListener("pointerup", (e) => {
  if (!downAt || Math.hypot(e.clientX - downAt[0], e.clientY - downAt[1]) > 8 || !playable()) return;
  const pt = groundPoint(e.clientX, e.clientY);
  if (!pt) return;
  const dx = pt.x - ball.position.x, dz = pt.z - ball.position.z;
  if (Math.hypot(dx, dz) > 9) return;
  const d = Math.hypot(dx, dz);
  game.vel.set(dx / d, dz / d).multiplyScalar(Math.sqrt(2 * MU * d)); // steady friction: rolls out exactly to the point you picked
