  const toCup = Math.hypot(b.x, b.z), speed = game.vel.length();
  if (toCup < 0.1 && speed < 1.4) { // dropped in
    game.rolling = false; game.holed = true; game.made++;
    b.x = b.z = 0;
    toast(game.putts === 1 ? "In the hole. One putt!" : `Holed in ${game.putts}. Nice touch.`);
    blip(880, 0.25); setTimeout(() => blip(1320, 0.2), 120);
    setTimeout(respawn, 2400);
  } else if (speed === 0 || toCup > 11 || game.rollT > 10) { // rollT: safety stop on steep rough
    game.rolling = false;
    if (toCup > 11) respawn(); else { readLine.visible = true; drawRead(); }
  }
}

// --- live coach panel, wind and chapter dots
const coach = Object.fromEntries([...document.querySelectorAll("[data-c]")].map((el) => [el.dataset.c, el]));
const dots = [...document.querySelectorAll(".dots button")];
dots.forEach((d, n) => d.addEventListener("click", () => { goal = n; }));
let wind = 6;

function resize() {
  const w = innerWidth, h = innerHeight;
  renderer.setSize(w, h, false);
  camera.aspect = w / h;
  camera.fov = w / h < 1 ? 52 : 38; // portrait screens: widen so the flag still fits
  camera.updateProjectionMatrix();
}
addEventListener("resize", resize);
resize();

const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
const v = new THREE.Vector3();
const clock = new THREE.Clock();
let smoothP = scrollProgress();
renderer.setAnimationLoop(() => {
  const dt = Math.min(clock.getDelta(), 0.05), t = clock.elapsedTime;
  stepBall(dt);
  wind = 3 + noise(t * 0.08, 1.3) * 11;
  smoothP += (scrollProgress() - smoothP) * 0.08;
  const f = smoothP * (keys.length - 1), i = Math.min(Math.floor(f), keys.length - 2), k = smooth(f - i);
  camPos.lerpVectors(keys[i].p, keys[i + 1].p, k);
  camTgt.lerpVectors(keys[i].t, keys[i + 1].t, k);
  if (camera.aspect < 1) camPos.sub(camTgt).multiplyScalar(1.25).add(camTgt); // desktop intro: higher, like the original
  mouseS.lerp(mouse, 0.05);
  camera.position.copy(camPos).add(v.set(mouseS.x * 0.6, -mouseS.y * 0.3, 0));
  camera.lookAt(camTgt);

  // flag wave: displacement grows away from the pole
  const a = flagGeo.attributes.position;
  for (let j = 0; j < a.count; j++) {
    const x = flagRest[j * 3], y = flagRest[j * 3 + 1], w = x / FW;
    const amp = 0.4 + wind / 9; // flag follows the live wind reading
    a.setZ(j, reduce ? w * 0.08 : (Math.sin(x * 6 - t * (2 + wind * 0.35) + y * 2) * 0.09 * w + Math.sin(x * 3 - t * 2.3) * 0.05 * w) * amp);
  }
  a.needsUpdate = true;
  flagGeo.computeVertexNormals();

  if (!reduce) { strokes.position.y = Math.sin(t * 0.3) * 0.3; specks.rotation.y = t * 0.02; }

  for (const { el, p } of tags) {
    v.copy(p).project(camera);
    const vis = v.z < 1 && Math.abs(v.x) < 1.1 && Math.abs(v.y) < 1.1;
    el.style.opacity = vis ? 1 : 0;
    el.style.transform = `translate(${((v.x + 1) / 2) * innerWidth + 6}px, ${((1 - v.y) / 2) * innerHeight - 14}px)`;
  }
  hudBottom.style.opacity = Math.max(0, 1 - goal * 4);
  const active = Math.round(smoothP * MAX) - 1;
  chapters.forEach((c, n) => c.classList.toggle("on", n === active));
  dots.forEach((d, n) => d.setAttribute("aria-current", n === active + 1));
  document.body.classList.toggle("deep", goal > 0.3);
  const live = Math.hypot(ball.position.x, ball.position.z);
  coach.pin.textContent = game.holed ? "in the cup" : `${(live * 3.281).toFixed(1)} ft`;
  coach.brk.textContent = game.rolling ? "rolling…" : read.cups ? `${read.cups} cup${read.cups > 1 ? "s" : ""} ${read.side}` : "straight";
  coach.pace.textContent = read.dist > 3 ? "firm" : read.dist > 1.5 ? "medium" : "die it in";
  coach.wind.textContent = `${wind.toFixed(0)} mph NE`;
  coach.putts.textContent = `${game.putts} · holed ${game.made}`;
  renderer.render(scene, camera);
});

// --- sound: soft procedural wind (no audio files)
const btn = document.getElementById("sound");
let ctx, gain;
function blip(freq, len) { // putter tock / cup rattle, only when sound is on
