input.new_string:
const clock = new THREE.Clock();
let smoothP = scrollProgress(), sunk = false;
const DROP = 0.96; // the ball reaches the cup here; the rest of the scroll it drops in
renderer.setAnimationLoop(() => {
  const dt = Math.min(clock.getDelta(), 0.05), t = clock.elapsedTime;
  wind = 3 + noise(t * 0.08, 1.3) * 11;
  smoothP += (scrollProgress() - smoothP) * 0.08;
  if (game.free && goal >= 0.02) backToLine(); // scrolling takes the ball back to the scripted putt
  const u = Math.min(smoothP / DROP, 1);
  if (game.free) stepBall(dt);
  else {
    placeOnPath(u);
    if (smoothP > DROP) ball.position.y -= ((smoothP - DROP) / (1 - DROP)) * 0.12;
    if (smoothP > 0.985 && !sunk) { sunk = true; toast("In the hole. Read it, roll it."); blip(880, 0.25); setTimeout(() => blip(1320, 0.2), 120); }
    if (smoothP < 0.9) sunk = false;
  }
