file.content:
if (game.free && goal >= 0.02) backToLine(); // scrolling takes the ball back to the scripted putt
const u = Math.min(smoothP / DROP, 1);
if (game.free) stepBall(dt);
else {
  placeOnPath(u);
  if (smoothP > DROP) ball.position.y -= ((smoothP - DROP) / (1 - DROP)) * 0.12;
  if (smoothP > 0.985 && !sunk) { sunk = true; toast("In the hole. Read it, roll it."); blip(880, 0.25); setTimeout(() => blip(1320, 0.2), 120); }
  if (smoothP < 0.9) sunk = false;
}
chase(game.free ? 0 : u, game.free ? START3 : ball.position); // free play: camera holds the opening view
if (camera.aspect < 1) camPos.sub(camTgt).multiplyScalar(1.25).add(camTgt); // portrait: step back so ball and flag both fit
mouseS.lerp(mouse, 0.05);
camera.position.copy(camPos).add(v.set(mouseS.x * 0.6, -mouseS.y * 0.3, 0));
camera.lookAt(camTgt);

// flag wave: displacement grows away from the pole
const a = flagGeo.attributes.position;
for (let j = 0; j < a.count; j++) {
  const x = flagRest[j * 3], y = flagRest[j * 3 + 1], w = x / FW;
  const amp = 0.4 + wind / 9; // flag follows the live wind reading
  a.setZ(j, reduce ? w * 0.08 : (Math.sin(x * 6 - t * (2 + wind * 0.35) + y * 2) * 0.09 * w + Math.sin(x * 3 - t * 2.3) * 0.05 * w) * amp);
}
a.needsUpdate = true;
flagGeo.computeVertexNormals();

if (!reduce) { strokes.position.y = Math.sin(t * 0.3) * 0.3; specks.rotation.y = t * 0.02; }

for (const { el, p } of tags) {
  v.copy(p).project(camera);
  const vis = v.z < 1 && Math.abs(v.x) < 1.1 && Math.abs(v.y) < 1.1;
  el.style.opacity = vis ? 1 : 0;
  el.style.transform = `translate(${((v.x + 1) / 2) * innerWidth + 6}px, ${((1 - v.y) / 2) * innerHeight - 14}px)`;
}
hudBottom.style.opacity = Math.max(0, 1 - goal * 4);
const active = Math.round(smoothP * MAX) - 1;
chapters.forEach((c, n) => c.classList.toggle("on", n === active));
dots.forEach((d, n) => d.setAttribute("aria-current", n === active + 1));
document.body.classList.toggle("deep", goal > 0.3);
const live = Math.hypot(ball.position.x, ball.position.z);
coach.pin.textContent = game.holed ? "in the cup" : `${(live * 3.281).toFixed(1)} ft`;
coach.brk.textContent = game.rolling ? "rolling…" : read.cups ? `${read.cups} cup${read.cups > 1 ? "s" : ""} ${read.side}` : "straight";
coach.pace.textContent = read.dist > 3 ? "firm" : read.dist > 1.5 ? "medium" : "die it in";
coach.wind.textContent = `${wind.toFixed(0)} mph NE`;
coach.putts.textContent = `${game.putts} · holed ${game.made}`;
renderer.render(scene, camera);

