.pulse { width: 7px; height: 7px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 0 0 rgba(92,122,42,.6); animation: pulse 1.8s infinite; }
@keyframes pulse { 70% { box-shadow: 0 0 0 9px rgba(92,122,42,0); } 100% { box-shadow: 0 0 0 0 rgba(92,122,42,0); } }

.coach { right: var(--pad); bottom: var(--pad); width: 190px; padding: 12px 14px; background: rgba(242,240,232,.72); border: 1px solid var(--line); backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px); transition: opacity .4s; }
.coach .kicker { color: var(--accent); display: flex; justify-content: space-between; white-space: nowrap; }
.coach .live { color: var(--accent); animation: blink 2s infinite; }
.coach dl { display: grid; grid-template-columns: auto 1fr; gap: 3px 12px; margin-top: 8px; }
.coach dt { color: var(--muted); }
.coach dd { margin: 0; text-align: right; font-variant-numeric: tabular-nums; }
@keyframes blink { 50% { opacity: .35; } }
.deep .hint { opacity: 0; pointer-events: none; }

.dots { right: calc(var(--pad) * .45); top: 50%; transform: translateY(-50%); display: grid; gap: 12px; }
.dots button { width: 9px; height: 9px; padding: 0; border-radius: 50%; border: 1px solid var(--ink); background: transparent; cursor: pointer; transition: background .3s, transform .3s; }
.dots button:hover { transform: scale(1.3); }
.dots button[aria-current="true"] { background: var(--ink); }

.toast { position: fixed; z-index: 3; left: 50%; top: 22%; transform: translate(-50%, 10px) scale(.96); padding: 12px 20px; background: var(--ink); color: #f2f0e8; font: 400 22px/1 var(--display); letter-spacing: .03em; text-transform: uppercase; opacity: 0; transition: opacity .3s, transform .3s; pointer-events: none; white-space: nowrap; }
.toast.on { opacity: 1; transform: translate(-50%, 0) scale(1); }
.toast::before { content: ""; display: inline-block; width: 10px; height: 10px; margin-right: 10px; background: var(--gold); border-radius: 50%; }

@media (max-width: 500px) {
  .coach { width: 150px; padding: 10px; }
  .coach dl { gap: 2px 8px; }
  .toast { font-size: 17px; }
}
@media (prefers-reduced-motion: reduce) { .pulse, .coach .live { animation: none; } }

