const lineMat = new THREE.LineBasicMaterial({ color: "#1e211b", transparent: true, opacity: 0.6, fog: false, depthTest: false });
const lift = (x, z, y = 0.03) => new THREE.Vector3(x, height(x, z) + y, z);

// --- the scroll putt: an 18 ft breaking putt the ball rolls along as you scroll
const START = new THREE.Vector2(4.2, 3.6), SIDE = new THREE.Vector2(-START.y, START.x).normalize();
const path = new THREE.SplineCurve([
  START.clone(),
  START.clone().multiplyScalar(0.66).addScaledVector(SIDE, 0.45),
  START.clone().multiplyScalar(0.33).addScaledVector(SIDE, 0.35),
  new THREE.Vector2(0, 0),
]);
const PATH_LEN = path.getLength(), N = 240;
const pathPts = path.getSpacedPoints(N).map((q) => lift(q.x, q.y, 0.012));
// depthTest off: the lines lie on the grass and must not sink into the terrain mesh between its vertices
const trail = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pathPts), new THREE.LineBasicMaterial({ color: "#1e211b", transparent: true, opacity: 0.8, fog: false, depthTest: false }));
const ahead = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pathPts), new THREE.LineDashedMaterial({ color: "#f2f0e8", dashSize: 0.1, gapSize: 0.07, fog: false, depthTest: false }));
trail.renderOrder = ahead.renderOrder = 1;
ahead.computeLineDistances();
scene.add(trail, ahead);
const q2 = new THREE.Vector2(), tan2 = new THREE.Vector2();
function placeOnPath(u) { // ball at fraction u of the putt's length, rolling as it goes
  path.getPointAt(u, q2); path.getTangentAt(Math.min(u, 0.999), tan2);
  ball.position.set(q2.x, height(q2.x, q2.y) + 0.045, q2.y);
  ball.quaternion.setFromAxisAngle(v.set(tan2.y, 0, -tan2.x).normalize(), (u * PATH_LEN) / 0.045);
  const n = Math.round(u * N);
  trail.geometry.setDrawRange(0, n + 1);
  ahead.geometry.setDrawRange(n, N + 1 - n);
}
const v = new THREE.Vector3();
placeOnPath(0);
const slope = (x, z) => new THREE.Vector2((height(x + 0.05, z) - height(x - 0.05, z)) / 0.1, (height(x, z + 0.05) - height(x, z - 0.05)) / 0.1);
const readLine = new THREE.Line(new THREE.BufferGeometry(), lineMat);
scene.add(readLine);
const read = { dist: 0, side: "", cups: 0 };
function drawRead() { // coach's suggested line: bends against the slope across the putt
  const bx = ball.position.x, bz = ball.position.z, dist = Math.hypot(bx, bz);
  const perp = new THREE.Vector2(-bz, bx).normalize();
  const g = slope(bx / 2, bz / 2).dot(perp);
  const off = THREE.MathUtils.clamp(g * dist * 1.5, -0.8, 0.8);
  const curve = new THREE.CatmullRomCurve3([lift(bx, bz), lift(bx / 2 + perp.x * off, bz / 2 + perp.y * off), lift(0, 0)]);
  readLine.geometry.setFromPoints(curve.getPoints(60));
  Object.assign(read, { dist, side: off > 0 ? "R" : "L", cups: Math.max(0, Math.round(Math.abs(off) / 0.108)) });
}
drawRead();
readLine.visible = false; // only shown in free play; the scroll putt has its own line

const aimMat = new THREE.LineDashedMaterial({ color: "#5c7a2a", dashSize: 0.08, gapSize: 0.06, fog: false, depthTest: false });
const aimLine = new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]), aimMat);
const aimRing = new THREE.Mesh(new THREE.RingGeometry(0.07, 0.1, 32).rotateX(-Math.PI / 2), new THREE.MeshBasicMaterial({ color: "#5c7a2a", fog: false }));
aimLine.visible = aimRing.visible = false;
scene.add(aimLine, aimRing);

// distance markers along the putt; each dims once the ball rolls past it
const labelsEl = document.getElementById("labels");
const marks = [[15, "Pace check · firm stroke"], [10, "Break starts here"], [6, "Slope 1.4% · downhill"], [3, "Die it in the front edge"]];
const tags = marks.map(([ft, tip]) => {
  const u = 1 - ft / 3.281 / PATH_LEN;
  path.getPointAt(u, q2);
  const el = document.createElement("span"); el.className = "tag"; el.textContent = `${ft} ft`; el.dataset.tip = tip; el.tabIndex = 0;
  labelsEl.append(el); return { el, p: lift(q2.x, q2.y, 0.02), u };
});

