// One-shot check: serve dist/, open it in headless Chrome, putt at the hole until it drops.
// Usage: node scripts/play-check.mjs [path-to-chrome]   (exits when done)
import { createServer } from "node:http";
import { readFile, mkdtemp } from "node:fs/promises";
import { spawn } from "node:child_process";
import { tmpdir } from "node:os";
import { join, extname } from "node:path";

const dist = new URL("../dist/", import.meta.url);
const types = { ".html": "text/html", ".js": "text/javascript", ".css": "text/css", ".woff2": "font/woff2", ".woff": "font/woff" };
const server = createServer(async (req, res) => {
  const path = req.url === "/" ? "index.html" : decodeURIComponent(req.url.slice(1).split("?")[0]);
  try { res.writeHead(200, { "content-type": types[extname(path)] || "application/octet-stream" }).end(await readFile(new URL(path, dist))); }
  catch { res.writeHead(404).end(); }
}).listen(0);
const url = `http://127.0.0.1:${server.address().port}/`;

const chrome = process.argv.slice(2).find((a) => !a.startsWith("--")) || "C:/Program Files/Google/Chrome/Application/chrome.exe";
const profile = await mkdtemp(join(tmpdir(), "play-check-"));
const browser = spawn(chrome, ["--headless=new", "--remote-debugging-port=0", `--user-data-dir=${profile}`, "--window-size=1440,900",
  "--enable-unsafe-swiftshader", "--use-angle=swiftshader", "--no-first-run", url]);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const done = (code, msg) => { console.log(msg); browser.kill(); server.close(); process.exit(code); };
setTimeout(() => done(1, "FAIL: timed out"), 90000);

const port = await new Promise((resolve) => {
  let buf = "";
  browser.stderr.on("data", (d) => { buf += d; const m = buf.match(/127\.0\.0\.1:(\d+)\//); if (m) resolve(m[1]); });
});
let page;
for (let n = 0; n < 40 && !page; n++) { await sleep(250); page = (await (await fetch(`http://127.0.0.1:${port}/json/list`)).json()).find((t) => t.type === "page"); }
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => ws.addEventListener("open", r));
let id = 0; const waiting = new Map();
ws.addEventListener("message", (e) => {
  const m = JSON.parse(e.data);
  if (m.error) console.log("cdp error", JSON.stringify(m.error));
  waiting.get(m.id)?.(m.result); waiting.delete(m.id);
});
console.log("connected");
const cdp = (method, params = {}) => new Promise((r) => { waiting.set(++id, r); ws.send(JSON.stringify({ id, method, params })); });
const read = async () => (await cdp("Runtime.evaluate", { expression:
  `JSON.stringify({ pin: document.querySelector('[data-c=pin]').textContent, putts: document.querySelector('[data-c=putts]').textContent, brk: document.querySelector('[data-c=brk]').textContent, toast: document.getElementById('toast').classList.contains('on') ? document.getElementById('toast').textContent : '' })`,
})).result.value;

const phone = process.argv.includes("--phone"); // 390x900 with finger taps instead of mouse clicks
await cdp("Emulation.setDeviceMetricsOverride", { width: phone ? 390 : 1440, height: 900, deviceScaleFactor: 1, mobile: phone });
if (phone) await cdp("Emulation.setTouchEmulationEnabled", { enabled: true, maxTouchPoints: 1 });
await sleep(4000); // fonts, first frames
console.log("viewport", (await cdp("Runtime.evaluate", { expression: "innerWidth + 'x' + innerHeight" })).result.value);
console.log("start", await read());

if (process.argv.includes("--scroll")) { // scroll putt: wheel down in steps, save a picture at each, expect the ball in the cup at the end
  const { writeFile, mkdir } = await import("node:fs/promises");
  const out = join(tmpdir(), "golf-shots"); await mkdir(out, { recursive: true });
  let sawToast = false;
  for (const [step, name] of [[0, "0"], [1, "1"], [1, "2"], [0.6, "2.6"], [0.4, "3"]]) {
    if (step) await cdp("Input.dispatchMouseEvent", { type: "mouseWheel", x: 300, y: 300, deltaX: 0, deltaY: step * 900 });
    for (let n = 0; n < 16; n++) { await sleep(250); if (JSON.parse(await read()).toast) sawToast = true; }
    const png = (await cdp("Page.captureScreenshot", { format: "png" })).data;
    await writeFile(join(out, `${phone ? "phone" : "desk"}-${name}.png`), Buffer.from(png, "base64"));
    console.log(`goal ${name}`, await read());
  }
  const end = JSON.parse(await read());
  done(end.pin === "in the cup" && sawToast ? 0 : 1, `${end.pin === "in the cup" && sawToast ? "PASS" : "FAIL"}: scroll putt ends in the cup (pictures in ${out})`);
}

const holeArg = process.argv.find((a) => a.startsWith("--hole="))?.slice(7).split(",").map(Number);
const HOLE = holeArg ? { x: holeArg[0], y: holeArg[1] } : phone ? { x: 231, y: 453 } : { x: 778, y: 454 }; // cup on screen (from the check screenshots)
for (let putt = 1; putt <= 6; putt++) {
  if (phone) {
    await cdp("Input.dispatchTouchEvent", { type: "touchStart", touchPoints: [HOLE] });
    await cdp("Input.dispatchTouchEvent", { type: "touchEnd", touchPoints: [] });
  } else for (const type of ["mouseMoved", "mousePressed", "mouseReleased"])
