:root {
  --bg: #ece9e0;
  --ink: #1e211b;
  --muted: #4a4e44;
  --accent: #5c7a2a;
  --accent-strong: #465e1f;
  --gold: #e8c547;
  --line: #c9c5b8;
  --pad: clamp(24px, 6.5vw, 50px);
  --mono: "Space Mono", ui-monospace, monospace;
  --display: "Anton", Impact, system-ui, sans-serif;
}
* { box-sizing: border-box; margin: 0; }
html, body { background: var(--bg); color: var(--ink); overflow-x: hidden; }
body { font-family: var(--mono); -webkit-font-smoothing: antialiased; }
#scene { position: fixed; inset: 0; width: 100%; height: 100%; display: block; }
#labels { position: fixed; inset: 0; pointer-events: none; overflow: hidden; }
.tag { position: absolute; left: 0; top: 0; font: 400 11px/1 var(--mono); color: var(--ink); text-shadow: 0 0 6px rgba(242,240,232,.8); white-space: nowrap; }
.tag::before { content: "+"; position: absolute; left: -4px; top: 6px; font-size: 13px; }

.mono { font: 400 12px/1.32 var(--mono); letter-spacing: .01em; text-shadow: 0 0 8px rgba(242,240,232,.6); }
.hud { position: fixed; z-index: 2; animation: fade 1.2s .2s both; }
.hud-left { top: var(--pad); left: var(--pad); }
.hud-left .mono { margin-top: 12px; }
.hud-left .mono + .mono { margin-top: 14px; }
.logo { display: inline-flex; align-items: flex-start; font: 400 clamp(32px, 6.4vw, 62px)/0.8 var(--display); letter-spacing: .01em; color: var(--ink); text-decoration: none; text-transform: uppercase; }
.logo .flag { width: .3em; height: .8em; margin: 0 .1em 0 .12em; border-left: .07em solid currentColor; position: relative; }
.logo .flag::after { content: ""; position: absolute; left: 0; top: 0; border-left: .26em solid var(--gold); border-top: .14em solid transparent; border-bottom: .14em solid transparent; }
.hud-right { top: var(--pad); right: var(--pad); text-align: right; }
.hud-right .manifesto { margin-top: 10px; width: 11.2em; margin-left: auto; }
.hud-bottom { left: var(--pad); bottom: var(--pad); }
.sound { margin-top: 18px; display: flex; align-items: center; gap: 8px; background: rgba(242,240,232,.85); border: 1px solid var(--line); padding: 5px 10px 5px 8px; color: inherit; text-shadow: none; cursor: pointer; }
.sound:hover, .sound:focus-visible { border-color: var(--accent); }
.sound b { font-weight: 400; }
.sound .w { display: none; }
.sound[aria-pressed="true"] .w { display: inline; }
.sound[aria-pressed="true"] .x { display: none; }

html, body { height: 100%; overflow: hidden; overscroll-behavior: none; }
main { position: fixed; inset: 0; z-index: 1; pointer-events: none; }
section { position: absolute; inset: 0; display: flex; align-items: center; padding: 0 var(--pad); opacity: 0; transform: translateY(24px); transition: opacity .6s, transform .6s; }
section.on { opacity: 1; transform: none; pointer-events: auto; }
.chapter.right { justify-content: flex-end; }
/* --- chapter slides */
.panel { width: min(540px, 100%); padding: 34px 36px 32px; background: rgba(242, 240, 232, .88); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  border: 1px solid var(--line); border-top: 4px solid var(--accent); color: var(--ink); box-shadow: 0 24px 60px -30px rgba(30, 33, 27, .45); }
.panel-top { display: flex; align-items: flex-end; gap: 16px; }
.num { font: 400 76px/.8 var(--display); color: transparent; -webkit-text-stroke: 1.5px var(--ink); letter-spacing: .02em; }
.panel .kicker { font: 400 12px/1 var(--mono); color: var(--accent); text-transform: uppercase; letter-spacing: .08em; padding-bottom: 6px; }
.panel h2 { font: 400 clamp(44px, 4.6vw, 70px)/.95 var(--display); letter-spacing: .005em; margin: 22px 0 18px; text-transform: uppercase; }
.panel h2 em { font-style: normal; color: var(--accent); background: linear-gradient(transparent 68%, rgba(232, 197, 71, .55) 68%, rgba(232, 197, 71, .55) 92%, transparent 92%); }
.lede { font: 400 18px/1.5 "Inter Tight", system-ui, sans-serif; color: var(--muted); max-width: 30em; }
.stats { list-style: none; padding: 20px 0 0; margin: 24px 0 0; border-top: 1px solid var(--line); display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.stats b { display: block; font: 400 36px/1 var(--display); letter-spacing: .01em; }
.stats span { display: block; margin-top: 6px; font: 400 11px/1.3 var(--mono); color: var(--muted); text-transform: uppercase; letter-spacing: .05em; }
.cta { display: inline-flex; align-items: center; gap: 10px; margin-top: 26px; padding: 14px 20px; border: 1px solid var(--accent); background: var(--accent); color: #fff; text-decoration: none; font: 500 16px/1 "Inter Tight", system-ui, sans-serif; transition: background .2s, gap .2s; }
.cta:hover, .cta:focus-visible { background: var(--accent-strong); border-color: var(--accent-strong); gap: 16px; }
/* pieces slide in one after another when a slide appears */
.panel > * { opacity: 0; transform: translateY(14px); transition: opacity .5s, transform .5s; }
section.on .panel > * { opacity: 1; transform: none; }
section.on .panel > :nth-child(2) { transition-delay: .08s; }
section.on .panel > :nth-child(3) { transition-delay: .16s; }
section.on .panel > :nth-child(4) { transition-delay: .24s; }
section.on .panel > :nth-child(5) { transition-delay: .32s; }
@media (prefers-reduced-motion: reduce) { .panel > * { transition: none; } }

@keyframes fade { from { opacity: 0; } to { opacity: 1; } }

@media (max-width: 500px) {
  .mono { font-size: 11px; }
