  .panel h2 { font-size: 36px; margin: 16px 0 12px; }
  .lede { font-size: 15px; }
  .stats { margin-top: 16px; padding-top: 14px; gap: 10px; }
  .stats b { font-size: 24px; }
  .stats span { font-size: 10px; }
  .cta { margin-top: 18px; padding: 12px 16px; font-size: 15px; }
  section { align-items: flex-end; padding-bottom: 150px; }
}
@media (prefers-reduced-motion: reduce) { .hud { animation: none; } }

/* light falls from the upper right, like the original's scene */
body::after { content: ""; position: fixed; inset: 0; z-index: 0; pointer-events: none;
  background: linear-gradient(to top right, rgba(30, 33, 27, .22), rgba(30, 33, 27, 0) 50%, rgba(255, 250, 235, .12)); }

