.pulse { width: 7px; height: 7px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 0 0 rgba(92,122,42,.6); animation: pulse 1.8s infinite; }
@keyframes pulse { 70% { box-shadow: 0 0 0 9px rgba(92,122,42,0); } 100% { box-shadow: 0 0 0 0 rgba(92,122,42,0); } }

.coach { right: var(--pad); bottom: var(--pad); width: 190px; padding: 12px 14px; background: rgba(242,240,232,.72); border: 1px solid var(--line); backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px); transition: opacity .4s; }
.coach .kicker { color: var(--accent); display: flex; justify-content: space-between; white-space: nowrap; }
