input.new_string:
const grain = (() => { // tiling turf: thousands of tiny blade strokes (no image files); tinted by the vertex colours
  const S = 512, c = document.createElement("canvas"); c.width = c.height = S;
  const g = c.getContext("2d");
  g.fillStyle = "rgb(205,205,205)"; g.fillRect(0, 0, S, S);
  g.lineCap = "round";
  for (let n = 0; n < 14000; n++) {
    const x = Math.random() * S, y = Math.random() * S, len = 3 + Math.random() * 6, a = -Math.PI / 2 + (Math.random() - 0.5) * 0.9;
    const v = 150 + Math.random() * 105 | 0;
    g.strokeStyle = `rgb(${v},${v},${v})`; g.lineWidth = 0.6 + Math.random() * 0.9;
    for (const ox of [0, -S, S]) for (const oy of [0, -S, S]) { // draw wrapped so the tile is seamless
      g.beginPath(); g.moveTo(x + ox, y + oy); g.lineTo(x + ox + Math.cos(a) * len, y + oy + Math.sin(a) * len); g.stroke();
    }
  }
  const t = new THREE.CanvasTexture(c); t.wrapS = t.wrapT = THREE.RepeatWrapping; t.repeat.set(110, 110); t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 8;
  return t;
})();

