let ctx, gain;
function blip(freq, len) { // putter tock / cup rattle, only when sound is on
  if (!ctx || btn.getAttribute("aria-pressed") !== "true") return;
  const o = ctx.createOscillator(), g = ctx.createGain();
  o.frequency.value = freq;
  g.gain.setValueAtTime(0.25, ctx.currentTime); g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + len);
  o.connect(g).connect(ctx.destination); o.start(); o.stop(ctx.currentTime + len);
}
btn.addEventListener("click", () => {
  if (!ctx) {
    ctx = new AudioContext();
    const buf = ctx.createBuffer(1, ctx.sampleRate * 4, ctx.sampleRate), d = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < d.length; i++) { last = (last + 0.02 * (Math.random() * 2 - 1)) / 1.02; d[i] = last * 3.5; }
    const src = Object.assign(ctx.createBufferSource(), { buffer: buf, loop: true });
    const lp = Object.assign(ctx.createBiquadFilter(), { type: "lowpass" }); lp.frequency.value = 500;
    gain = ctx.createGain(); gain.gain.value = 0;
    src.connect(lp).connect(gain).connect(ctx.destination); src.start();
  }
  const on = btn.getAttribute("aria-pressed") !== "true";
  btn.setAttribute("aria-pressed", on);
  btn.querySelector("b").textContent = on ? "On" : "Off";
  ctx.resume();
  gain.gain.setTargetAtTime(on ? 0.5 : 0, ctx.currentTime, 0.3);
});

