// --- sound: a small procedural soundscape (no audio files)
// stereo wind that gusts with the live wind reading, birdsong, putter tock, rolling rumble, cup rattle, slide ticks
const sfx = (() => {
  let ctx, master, windGain, windLP, rollGain, noise, on = false;
  const rand = (a, b) => a + Math.random() * (b - a);
  function init() {
    ctx = new AudioContext();
    const sr = ctx.sampleRate;
    master = ctx.createGain(); master.gain.value = 0;
    const comp = ctx.createDynamicsCompressor(); master.connect(comp).connect(ctx.destination);
    noise = ctx.createBuffer(1, sr * 2, sr);
    noise.getChannelData(0).forEach((_, i, d) => { d[i] = Math.random() * 2 - 1; });
    const brown = ctx.createBuffer(2, sr * 6, sr); // a different brown-noise stream per ear = wide wind
    for (let ch = 0; ch < 2; ch++) { let last = 0; brown.getChannelData(ch).forEach((_, i, d) => { last = (last + 0.02 * (Math.random() * 2 - 1)) / 1.02; d[i] = last * 3.5; }); }
    const wind = Object.assign(ctx.createBufferSource(), { buffer: brown, loop: true });
    windLP = Object.assign(ctx.createBiquadFilter(), { type: "lowpass" }); windLP.frequency.value = 400;
    windGain = ctx.createGain(); windGain.gain.value = 0.2;
    wind.connect(windLP).connect(windGain).connect(master); wind.start();
    const roll = Object.assign(ctx.createBufferSource(), { buffer: noise, loop: true });
    const rollLP = Object.assign(ctx.createBiquadFilter(), { type: "lowpass", Q: { value: 0 } }); rollLP.frequency.value = 260;
    rollGain = ctx.createGain(); rollGain.gain.value = 0;
    roll.connect(rollLP).connect(rollGain).connect(master); roll.start();
    birds();
  }
  function out(pan) { const p = ctx.createStereoPanner(); p.pan.value = pan; p.connect(master); return p; }
  function burst(t, dur, freq, q, vol, pan = 0) { // filtered noise hit
    const s = Object.assign(ctx.createBufferSource(), { buffer: noise });
    const bp = Object.assign(ctx.createBiquadFilter(), { type: "bandpass" }); bp.frequency.value = freq; bp.Q.value = q;
    const g = ctx.createGain(); g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.0008, t + dur);
    s.connect(bp).connect(g).connect(out(pan)); s.start(t, Math.random()); s.stop(t + dur + 0.02);
  }
  function tone(t, f0, f1, dur, vol, type = "sine", pan = 0) { // swept, enveloped oscillator
    const o = Object.assign(ctx.createOscillator(), { type });
    o.frequency.setValueAtTime(f0, t); o.frequency.exponentialRampToValueAtTime(f1, t + dur);
    const g = ctx.createGain(); g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(vol, t + 0.006); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g).connect(out(pan)); o.start(t); o.stop(t + dur + 0.02);
  }
  function birds() { // a short phrase from somewhere left or right every few seconds
    setTimeout(() => {
      if (on) {
        const base = rand(2400, 4200), pan = rand(-0.8, 0.8), n = 2 + (Math.random() * 5 | 0);
        let t = ctx.currentTime;
        for (let i = 0; i < n; i++) { const f = base * rand(0.85, 1.25); tone(t, f, f * rand(0.65, 1.4), rand(0.05, 0.12), 0.035, "sine", pan); t += rand(0.08, 0.2); }
      }
      birds();
    }, rand(2500, 8000));
  }
  const live = () => on && ctx;
  return {
    toggle(v) {
      if (!ctx) init();
      on = v; ctx.resume();
      master.gain.setTargetAtTime(v ? 0.9 : 0, ctx.currentTime, 0.25);
    },
    update(windMph, rollSpeed) { // called every frame
      if (!ctx) return;
      const t = ctx.currentTime;
      windGain.gain.setTargetAtTime(0.12 + windMph * 0.03, t, 0.6);
      windLP.frequency.setTargetAtTime(220 + windMph * 60, t, 0.6);
      rollGain.gain.setTargetAtTime(Math.min(rollSpeed, 2.5) * 0.22, t, 0.05);
    },
    putt(power = 1) { // club face on ball: a bright click over a hollow body
      if (!live()) return; const t = ctx.currentTime + 0.01;
      burst(t, 0.045, 2100, 1.4, 0.55 * power); tone(t, 1150, 680, 0.08, 0.22 * power, "triangle");
    },
    cup() { // ball rattling against the plastic liner, then settling
      if (!live()) return; const t = ctx.currentTime + 0.02;
      [0, 0.075, 0.13, 0.17, 0.2].forEach((d, i) => burst(t + d, 0.035, 3000 - i * 220, 5, 0.32 - i * 0.05));
      tone(t + 0.21, 230, 150, 0.28, 0.25);
    },
    tick() { if (live()) tone(ctx.currentTime, 2600, 2100, 0.035, 0.04, "sine"); },
  };
})();
const btn = document.getElementById("sound");
btn.addEventListener("click", () => {
  const on = btn.getAttribute("aria-pressed") !== "true";
  btn.setAttribute("aria-pressed", on);
  btn.querySelector("b").textContent = on ? "On" : "Off";
  sfx.toggle(on);
});

